+                         {error}"
+                    );
+                    crate::error::EXIT_REFUSED
+                }
+            }
+        }
+        Err(error) => {
+            eprintln!("onevcs: {error}");
+            i32::from(onevcs::FailureKind::of(&error).exit_code())
